// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;
import java.util.function.Supplier;

public final class NativeExecutionTestRetries {

	private NativeExecutionTestRetries() {
	}

	/** Refreshes an execution explanation once after pending compilation has had a chance to finish. */
	public static <T> T retryInterpreted(T explanation, Supplier<T> explain, Function<T, List<String>> paths,
			List<String> expected) throws InterruptedException {
		List<String> actual = paths.apply(explanation);
		if (!hasOnlyInterpretedMismatches(actual, expected)) {
			return explanation;
		}
		assertThat(JaninoPipelineTestAccess.awaitCompilations(30, TimeUnit.SECONDS))
				.as("Janino compilations for %s to reach %s (%s)", actual, expected,
						JaninoPipelineTestAccess.cacheSummary())
				.isTrue();
		return explain.get();
	}

	private static boolean hasOnlyInterpretedMismatches(List<String> actual, List<String> expected) {
		if (actual.size() != expected.size()) {
			return false;
		}
		boolean mismatch = false;
		for (int i = 0; i < expected.size(); i++) {
			String route = expected.get(i);
			if (!route.equals(actual.get(i))) {
				if (!(route.startsWith("irKernel") || route.startsWith("irAggregate"))
						|| !actual.get(i).equals(route + "Interpreted")) {
					return false;
				}
				mismatch = true;
			}
		}
		return mismatch;
	}
}
